  "exclude": ["node_modules"]
}

export default function Home() {
  return (
    <main>
      <h1>User Preferences</h1>
      <p>Please implement the theme and language display here.</p>
    </main>
  )
}

import type { Metadata } from 'next'

export const metadata: Metadata = {
  title: 'Theme Settings',
  description: 'Display user theme and language preferences',
}

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode
}>) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  )
}

/// <reference types="next" />
/// <reference types="next/image-types/global" />
import "./.next/types/routes.d.ts";

// NOTE: This file should not be edited
// see https://nextjs.org/docs/app/api-reference/config/typescript for more information.

import { cookies, headers } from 'next/headers'

function getPreferredLanguage(acceptLanguage: string | null) {
  return acceptLanguage?.split(',')[0]?.split(';')[0]?.trim() || 'Not specified'
}

export default async function UserPreferences() {
  const cookieStore = await cookies()
  const headerStore = await headers()

  const theme = cookieStore.get('theme')?.value || 'light'
  const preferredLanguage = getPreferredLanguage(
    headerStore.get('accept-language'),
  )

  return (
    <section>
      <h2>Current Preferences</h2>
      <p>Theme: {theme}</p>
      <p>Preferred language: {preferredLanguage}</p>
    </section>
  )
}
